Problem:
A company makes raincoats and umbrellas with images of Latin alphabet on them using a printing machine. Due to the popularity of Latin alphabet, the company must make at least 1200 raincoats or umbrellas, in any combination, per week. Also, in one week, the printing machine must be kept running for at least 70 hours. A raincoat takes 0.3 hours of printing time and costs $7. An umbrella takes 0.5 hours of printing time and costs $12. Formulate this problem so as to minimize total production costs.

Model and facts:
{
 "model": {
  "variables": [
   {
    "name": "raincoats",
    "lower": 0.0,
    "upper": null,
    "integer": true
   },
   {
    "name": "umbrellas",
    "lower": 0.0,
    "upper": null,
    "integer": true
   }
  ],
  "objective": {
   "sense": "min",
   "terms": [
    {
     "var": "raincoats",
     "coef": 7.0
    },
    {
     "var": "umbrellas",
     "coef": 12.0
    }
   ]
  },
  "constraints": [
   {
    "name": "total_output",
    "terms": [
     {
      "var": "raincoats",
      "coef": 1.0
     },
     {
      "var": "umbrellas",
      "coef": 1.0
     }
    ],
    "sense": ">=",
    "rhs": 1200.0
   },
   {
    "name": "machine_hours",
    "terms": [
     {
      "var": "raincoats",
      "coef": 0.3
     },
     {
      "var": "umbrellas",
      "coef": 0.5
     }
    ],
    "sense": ">=",
    "rhs": 70.0
   }
  ]
 },
 "facts": {
  "objective": 8400.0,
  "values": {
   "raincoats": 1200.0,
   "umbrellas": 0.0
  },
  "binding": [
   "total_output"
  ],
  "slack": {
   "total_output": 0.0,
   "machine_hours": 290.0
  },
  "shadow_prices": null,
  "limits": {
   "total_output": {
    "dropped_improves": true,
    "loosened_improves": true
   },
   "machine_hours": {
    "dropped_improves": false,
    "loosened_improves": false
   }
  }
 }
}
